order(s,[U],['je-voudrais','petit','robe','bleu','sil-vous-plait'],[],'Соберите «Мне бы хотелось это маленькое синее платье, пожалуйста». Начните с рамки просьбы.',[('Je voudrais','жё вудрэ́'),('cette petite robe bleue,','сэт пётит роб блё́'),('s’il vous plaît.','силь ву плэ́')],'Je voudrais cette petite robe bleue, s’il vous plaît.','жё вудрэ сэт пётит роб блё, силь ву плэ́.','Получилась просьба с нужной вещью, размером и цветом.','Поставьте вежливую рамку, целое описание платья и пожалуйста.')
page(s,[('Размер и цвет',['В выбранных сочетаниях прилагательные согласуются с названием вещи. Русский род слова платье не определяет французскую форму.'],[ex('Un petit pull bleu. Une petite robe bleue.','Маленький синий свитер. Маленькое синее платье.','э(н) пёти пюль блё́. юн пётит роб блё́')]),('Указать нужную вещь',['Показаны формы для одного свитера, одного платья и нескольких свитеров. Здесь не требуется вся система указательных слов.'],[ex('Ce pull. Cette robe. Ces pulls.','Этот свитер. Это платье. Эти свитеры.','сё пю́ль. сэт ро́б. сэ пю́ль')]),('Нужный размер',['Можно назвать нужный размер отдельно, затем выбрать вещь. Отдельный список других вещей не меняет прямо высказанную просьбу.'],[W['taille']['example']])])

