page(s,[('Просьба о примерке',['Примерка не означает, что вещь уже куплена или оплачена. Готовый вопрос просит разрешения примерить выбранную вещь.'],[W['essayer']['example'],W['je-peux']['example']]),('Место примерки',['В магазине одежды используется название примерочной. Не переносите на него название спальни из описания жилья.'],[W['cabine']['example']]),('Неподходящий размер',['Слишком маленький отличается от просто маленького. В показанном женском сочетании сохраняется согласование.'],[W['trop']['example'],ex('Cette robe est trop petite.','Это платье слишком маленькое.','сэт роб э тро пёти́т')])])

